-- Provisioning oracle (review fix).
--
-- core.provision_account used to answer differently for "this card number exists" (a raw
-- unique violation) and "this fingerprint belongs to someone" (CONFLICT), and it stored whatever
-- card number the caller chose. Now:
--   * the caller hands in 1-5 CANDIDATE card numbers (generated by the card-number algorithm,
--     LLD §5.4, sequences n, n+1, ...); the first one not already in use is stored. Every
--     candidate must look like a DeluluMart number: 16 digits, prefix beginning with 0, and
--     failing the Luhn check (invariant 7: never a real card number). When every candidate is
--     taken, or the alias / DeluluPay-style id is taken, the call raises one generic retryable
--     error (BUSY) that does not say which value collided;
--   * a presented email or phone fingerprint that belongs to ANOTHER account raises one uniform
--     CONFLICT whose message does not say which fingerprint matched.

-- Does this 16-digit string pass the standard Luhn check? (packages/core/src/card luhnValid)
CREATE FUNCTION core.luhn_valid(num text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
  SELECT num ~ '^[0-9]{2,}$' AND (
    SELECT sum(CASE WHEN i % 2 = 1 THEN CASE WHEN d * 2 > 9 THEN d * 2 - 9 ELSE d * 2 END ELSE d END) % 10 = 0
      FROM (SELECT i, substr(num, length(num) - i, 1)::int AS d
              FROM generate_series(0, length(num) - 1) i) x)
$$;

-- A candidate a DeluluMart card can carry: 16 digits, leading 0, Luhn-invalid by construction.
CREATE FUNCTION core.is_delulu_card_number(num text) RETURNS boolean
LANGUAGE sql IMMUTABLE SET search_path = pg_catalog, pg_temp AS $$
  SELECT num IS NOT NULL AND num ~ '^0[0-9]{15}$' AND NOT core.luhn_valid(num)
$$;

-- The new signature (card_numbers text[]) is created, with the onboarding requirements, in 0024.
DROP FUNCTION core.provision_account(bytea, bytea, text, text, text);

REVOKE ALL ON FUNCTION core.luhn_valid(text), core.is_delulu_card_number(text) FROM PUBLIC;
